module freq_div(
	input CLK_in, RST,
	output CLK_50, CLK_10, CLK_1
);
// TODO: Please add your logic design here

	reg [3:0] cnt_10;
	reg [6:0] cnt_100;
	reg clk_50, clk_10, clk_1;

	assign CLK_50 = clk_50;
	assign CLK_10 = clk_10;
	assign CLK_1 = clk_1;


	always@(posedge CLK_in or posedge RST) begin
		if(RST==1'b1)begin
			clk_50 <= 0;
		end else begin
			clk_50 <= ~clk_50;
		end
	end

	always@(posedge CLK_in or posedge RST) begin
		if(RST==1'b1)begin
			cnt_10 <= 0;
			clk_10 <= 0;
		end else begin
			if(cnt_10==4'd9)begin
				clk_10 <= ~clk_10;
				cnt_10 <= 0;
			end else begin
				cnt_10 <= cnt_10 + 1;
			end
		end
	end

	always@(posedge CLK_in or posedge RST) begin
		if(RST==1'b1)begin
			cnt_100 <= 0;
			clk_1 <= 0;
		end else begin
			if(cnt_100==7'd99)begin
				clk_1 <= ~clk_1;
				cnt_100 <= 0;
			end else begin
				cnt_100 <= cnt_100 + 1;
			end
		end
	end



endmodule
